create table public.xp_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,activity_type text not null,reward_reference text not null,xp integer not null check(xp>0),created_at timestamptz not null default now(),unique(user_id,reward_reference));
create table public.learning_activity(user_id uuid not null references auth.users(id) on delete cascade,activity_date date not null,activity_type text not null,created_at timestamptz not null default now(),primary key(user_id,activity_date,activity_type));
create table public.user_streaks(user_id uuid primary key references auth.users(id) on delete cascade,current_streak integer not null default 0,longest_streak integer not null default 0,last_activity_date date);
create table public.badges(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,criteria jsonb not null,created_at timestamptz not null default now());
create table public.user_badges(user_id uuid not null references auth.users(id) on delete cascade,badge_id uuid not null references public.badges(id) on delete cascade,earned_at timestamptz not null default now(),primary key(user_id,badge_id));
create table public.affiliate_settings(id boolean primary key default true check(id),commission_percent numeric(5,2) not null default 10 check(commission_percent between 0 and 100),minimum_payout_paise integer not null default 50000);
insert into public.affiliate_settings(id) values(true) on conflict do nothing;
create table public.referral_codes(user_id uuid primary key references auth.users(id) on delete cascade,code text not null unique check(code ~ '^[A-Z0-9]{6,20}$'),created_at timestamptz not null default now());
create table public.referrals(id uuid primary key default gen_random_uuid(),referrer_user_id uuid not null references auth.users(id),referred_user_id uuid not null unique references auth.users(id),created_at timestamptz not null default now(),check(referrer_user_id<>referred_user_id));
create table public.referral_commissions(id uuid primary key default gen_random_uuid(),referral_id uuid not null references public.referrals(id),payment_id uuid not null unique references public.payments(id),amount_paise integer not null check(amount_paise>0),status text not null default 'pending' check(status in ('pending','eligible','paid','reversed')),created_at timestamptz not null default now());
create table public.referral_payouts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),amount_paise integer not null check(amount_paise>0),upi_id text not null,payout_reference text not null unique,recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default now());
create table public.admin_audit_logs(id uuid primary key default gen_random_uuid(),admin_user_id uuid not null references auth.users(id),action text not null,target_type text not null,target_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.platform_settings(key text primary key,value jsonb not null,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
alter table public.xp_transactions enable row level security;alter table public.learning_activity enable row level security;alter table public.user_streaks enable row level security;alter table public.badges enable row level security;alter table public.user_badges enable row level security;alter table public.referral_codes enable row level security;alter table public.referrals enable row level security;alter table public.referral_commissions enable row level security;alter table public.referral_payouts enable row level security;alter table public.admin_audit_logs enable row level security;alter table public.platform_settings enable row level security;
create policy xp_own on public.xp_transactions for select to authenticated using(user_id=(select auth.uid()));create policy activities_own on public.learning_activity for select to authenticated using(user_id=(select auth.uid()));create policy streak_own on public.user_streaks for select to authenticated using(user_id=(select auth.uid()));create policy badges_read on public.badges for select to authenticated using(true);create policy user_badges_own on public.user_badges for select to authenticated using(user_id=(select auth.uid()));create policy referral_code_own on public.referral_codes for select to authenticated using(user_id=(select auth.uid()));create policy referrals_own on public.referrals for select to authenticated using(referrer_user_id=(select auth.uid()) or referred_user_id=(select auth.uid()));create policy commission_own on public.referral_commissions for select to authenticated using(exists(select 1 from public.referrals r where r.id=referral_id and r.referrer_user_id=(select auth.uid())));create policy payouts_own on public.referral_payouts for select to authenticated using(user_id=(select auth.uid()));
revoke all on public.xp_transactions,public.learning_activity,public.user_streaks,public.badges,public.user_badges,public.referral_codes,public.referrals,public.referral_commissions,public.referral_payouts,public.admin_audit_logs,public.platform_settings from anon,authenticated;
grant select on public.xp_transactions,public.learning_activity,public.user_streaks,public.badges,public.user_badges,public.referral_codes,public.referrals,public.referral_commissions,public.referral_payouts to authenticated;
